module sync_fifo #(parameter WIDTH=8,DEPTH=16)(input wire clk,rst_n,wr_en,rd_en,input wire [WIDTH-1:0] din,output reg [WIDTH-1:0] dout,output wire full,empty,output reg [$clog2(DEPTH):0] count); localparam PTR_W=$clog2(DEPTH); reg [WIDTH-1:0] mem[0:DEPTH-1]; reg [PTR_W-1:0] wr_ptr,rd_ptr; assign full=(count==DEPTH); assign empty=(count==0); always @(posedge clk or negedge rst_n) begin if(!rst_n)begin wr_ptr<=0;rd_ptr<=0;count<=0;dout<=0;end else begin if(wr_en&&!full)begin mem[wr_ptr]<=din;wr_ptr<=(wr_ptr==DEPTH-1)?0:wr_ptr+1'b1;end if(rd_en&&!empty)begin dout<=mem[rd_ptr];rd_ptr<=(rd_ptr==DEPTH-1)?0:rd_ptr+1'b1;end case({wr_en&&!full,rd_en&&!empty}) 2'b10:count<=count+1'b1;2'b01:count<=count-1'b1;default:count<=count;endcase end end endmodule
